import XCTest
@testable import Cotabby

/// Tests for the clipboard privacy rules: which pasteboard markers keep a copy out of prompts, and
/// how clipboard text is redacted before it reaches one.
final class ClipboardPrivacyPolicyTests: XCTestCase {

    // MARK: - Marker types

    func test_eachNSPasteboardMarkerExcludesTheCopy() {
        for marker in [
            "org.nspasteboard.ConcealedType",
            "org.nspasteboard.TransientType",
            "org.nspasteboard.AutoGeneratedType"
        ] {
            XCTAssertTrue(
                ClipboardPrivacyPolicy.excludesContext(pasteboardTypes: ["public.utf8-plain-text", marker]),
                marker
            )
        }
    }

    func test_legacyPasswordManagerTypesExcludeTheCopy() {
        XCTAssertTrue(ClipboardPrivacyPolicy.excludesContext(pasteboardTypes: ["com.agilebits.onepassword"]))
        XCTAssertTrue(ClipboardPrivacyPolicy.excludesContext(pasteboardTypes: ["net.antelle.keeweb"]))
    }

    func test_ordinaryCopiesAreNotExcluded() {
        XCTAssertFalse(ClipboardPrivacyPolicy.excludesContext(pasteboardTypes: []))
        XCTAssertFalse(ClipboardPrivacyPolicy.excludesContext(pasteboardTypes: [
            "public.utf8-plain-text",
            "public.html",
            "org.nspasteboard.source"
        ]))
    }

    /// Cotabby's own paste write must carry markers its own reader honours, so a completion on the
    /// pasteboard during the restore window never comes back as clipboard context.
    func test_cotabbyPasteMarkersAreOnesTheReaderExcludes() {
        XCTAssertTrue(ClipboardPrivacyPolicy.markersForCotabbyPasteWrites.contains("org.nspasteboard.TransientType"))
        XCTAssertTrue(ClipboardPrivacyPolicy.markersForCotabbyPasteWrites.contains("org.nspasteboard.ConcealedType"))
        XCTAssertTrue(ClipboardPrivacyPolicy.excludesContext(
            pasteboardTypes: ClipboardPrivacyPolicy.markersForCotabbyPasteWrites
        ))
    }

    // MARK: - Prompt-safe text

    func test_proseIsUnchanged() {
        let text = "Meeting moved to Thursday at 3 PM, room 4B."
        XCTAssertEqual(ClipboardPrivacyPolicy.promptSafeText(text), text)
    }

    func test_secretInsideProseIsRedacted() throws {
        let text = "Use key sk-proj-abcdefghijklmnop1234 for staging"
        let safe = try XCTUnwrap(ClipboardPrivacyPolicy.promptSafeText(text))
        XCTAssertFalse(safe.contains("abcdefghijklmnop1234"))
        XCTAssertTrue(safe.contains("staging"))
    }

    func test_cardNumberIsRedacted() throws {
        let safe = try XCTUnwrap(ClipboardPrivacyPolicy.promptSafeText("card 4111 1111 1111 1111 for the order"))
        XCTAssertFalse(safe.contains("4111"))
    }

    func test_clipboardThatIsOnlyASecretIsDropped() {
        XCTAssertNil(ClipboardPrivacyPolicy.promptSafeText("ghp_abcdefghijklmnopqrstuvwxyz0123456789"))
        XCTAssertNil(ClipboardPrivacyPolicy.promptSafeText("  4111-1111-1111-1111  "))
    }

    /// Clipboard keeps its head downstream, so redaction must not apply history's tail-only cap.
    func test_longClipboardIsNotTruncated() {
        let text = String(repeating: "word ", count: 4_000)
        XCTAssertEqual(ClipboardPrivacyPolicy.promptSafeText(text), text)
    }
}
